const x = $json.body ?? $json;
const allowed = ['notice','deadline','event','resource'];
const type = String(x.type || '');
const title = String(x.title || '').trim();
const details = String(x.details || '').trim();
if (!allowed.includes(type)) throw new Error('Unsupported request type');
if (title.length < 3 || title.length > 160) throw new Error('Title must be 3-160 characters');
if (details.length < 3 || details.length > 1200) throw new Error('Details must be 3-1200 characters');
let requestedDate = null;
const rawDate = String(x.date || '').trim();
if (rawDate) {
  const d = new Date(rawDate + (rawDate.length === 10 ? 'T12:00:00+05:30' : ''));
  if (Number.isNaN(d.valueOf())) throw new Error('Invalid requested date');
  requestedDate = d.toISOString();
}
if (type === 'resource') {
  let u;
  try { u = new URL(details); } catch { throw new Error('Resource request must include a valid URL'); }
  if (!['https:','http:'].includes(u.protocol)) throw new Error('Resource URL must use HTTP or HTTPS');
}
return [{json:{row:{
  request_type:type, title, details,
  audience:String(x.audience || 'AI & DS students').slice(0,80),
  requested_date:requestedDate, status:'pending_review'
}}}];
